<template>
    <div>
        <h1>视频详情</h1>
        id:{{ this.$route.params.id }}
    </div>
</template>

<script>
export default {
    name: 'VideoDetail',
    // props: ['id'],
    data() {
        return {
            videoDetail: {}
        }
    },
    mounted(){
        this.setPageAttribute('detailVideo')
    },
    beforeDestroy(){
        this.removePageAttribute()
    },
    methods:{
        setPageAttribute(pageClass){
            document.documentElement.setAttribute('data-page',pageClass)
        },
        removePageAttribute(){
            document.documentElement.removeAttribute('data-page')
        }
    }
}
</script>

